"""Source-gated Native spawn adapter for the emergency-response intersection.

The scene packet is a local reviewer artifact. Without it, no actor is spawned.
CARLA is passed in at invocation and never imported for CPU tests.
"""
from __future__ import annotations

import hashlib
import json
from pathlib import Path

from emergency_scene import scene_geometry


def validate_site(packet_path: Path, *, case_id: str, map_opendrive: str) -> dict:
    packet = json.loads(Path(packet_path).read_text())
    if packet.get("case_id") != case_id or packet.get("cell_id") != "C109035" or packet.get("actor") != "emergency_vehicle_driver":
        raise ValueError("Reviewed packet identity mismatch")
    if not packet.get("reviewer") or not packet.get("source_citation"):
        raise ValueError("Reviewed site or original source citation missing")
    if packet.get("opendrive_sha256") != hashlib.sha256(map_opendrive.encode()).hexdigest():
        raise ValueError("Reviewed OpenDRIVE map hash mismatch")
    direction = packet.get("approach")
    reference = scene_geometry(direction, packet.get("intersection_station_m", 0.0))
    if packet.get("pedestrian_role") != reference["pedestrian_role"]:
        raise ValueError("Pedestrian recipient role mismatch")
    for key in ("ego_blueprint_id", "pedestrian_blueprint_id", "ego_transform", "pedestrian_transform"):
        if not packet.get(key):
            raise ValueError("Reviewed spawn packet missing: " + key)
    ex, ey = packet["ego_transform"]["location"][:2]
    px, py = packet["pedestrian_transform"]["location"][:2]
    if abs(ex - reference["ego_spawn_xy_m"][0]) > 1.0 or abs(ey - reference["ego_spawn_xy_m"][1]) > 1.0:
        raise ValueError("Ego route position differs from reviewed engineering geometry")
    if abs(px - reference["pedestrian_spawn_xy_m"][0]) > 1.0 or abs(py - reference["pedestrian_spawn_xy_m"][1]) > 1.0:
        raise ValueError("Pedestrian recipient position differs from reviewed engineering geometry")
    return packet


def create(world, carla_api, packet_path: Path, case_id: str):
    packet = validate_site(packet_path, case_id=case_id, map_opendrive=world.get_map().to_opendrive())
    def transform(item):
        x, y, z = item["location"]
        pitch, yaw, roll = item["rotation"]
        return carla_api.Transform(carla_api.Location(x, y, z), carla_api.Rotation(pitch, yaw, roll))
    blueprints = world.get_blueprint_library()
    ego_bp = blueprints.find(packet["ego_blueprint_id"])
    pedestrian_bp = blueprints.find(packet["pedestrian_blueprint_id"])
    if not ego_bp.id.startswith("vehicle.") or not pedestrian_bp.id.startswith("walker.pedestrian."):
        raise ValueError("Emergency vehicle or pedestrian blueprint classification mismatch")
    ego = world.try_spawn_actor(ego_bp, transform(packet["ego_transform"]))
    if ego is None:
        raise ValueError("Emergency vehicle spawn failed")
    pedestrian = None
    try:
        pedestrian = world.try_spawn_actor(pedestrian_bp, transform(packet["pedestrian_transform"]))
        if pedestrian is None:
            raise ValueError("Pedestrian spawn failed")
        ego.set_autopilot(False)
        return {"ego": ego, "pedestrian": pedestrian, "site_packet_sha256": hashlib.sha256(Path(packet_path).read_bytes()).hexdigest()}
    except Exception:
        if pedestrian is not None:
            pedestrian.destroy()
        ego.destroy()
        raise

"""Original Native pose readback for the emergency driver and pedestrian."""
from __future__ import annotations

import math


def sample_actor(actor, role: str) -> dict:
    if role not in ("ego", "pedestrian"):
        raise ValueError("Unknown original actor role")
    identity = getattr(actor, "id", None)
    if type(identity) is not int or identity < 0:
        raise ValueError("Original actor identity missing: " + role)
    pose = actor.get_transform()
    location = pose.location
    rotation = pose.rotation
    values = {
        "x_m": location.x, "y_m": location.y, "z_m": location.z,
        "roll_deg": rotation.roll, "pitch_deg": rotation.pitch,
        "yaw_deg": rotation.yaw,
    }
    if any(type(value) not in (int, float) or not math.isfinite(value)
           for value in values.values()):
        raise ValueError("Original actor pose invalid: " + role)
    return {"role": role, "actor_id": identity, **values}

"""Retain synchronized original CARLA camera images for a Native attempt.

The reader supplies the four images for one world frame. This adapter records
their BGRA pixels as lossless PNGs; it does not evaluate physical visibility.
"""
from __future__ import annotations

import hashlib
import io
import json
import zipfile
from pathlib import Path

from PIL import Image


CAMERAS = ("overview", "approach", "reference_corner", "driver_reference")
PROFILE_SIZES = {"overview": (1920, 1080), "approach": (1280, 720),
                 "reference_corner": (1280, 720), "driver_reference": (1280, 720)}


class CameraRecorder:
    """Callable camera adapter for native_capture.capture.

    frame_reader(native_frame) returns a mapping of CARLA Image objects. The
    reader owns sensor queues and must return the requested frame exactly.
    """

    def __init__(self, output: Path, frame_reader, *, case_id: str,
                 source_ids: dict, sizes: dict | None = None, binding=None):
        self.output = Path(output)
        self.frame_reader = frame_reader
        self.case_id = case_id
        self.sizes = sizes or PROFILE_SIZES
        if set(self.sizes) != set(CAMERAS) or set(source_ids) != set(CAMERAS):
            raise ValueError("Four camera dimensions and source IDs required")
        if any(len(size) != 2 or min(size) <= 0 for size in self.sizes.values()):
            raise ValueError("Camera dimensions invalid")
        if not all(isinstance(source_ids[key], str) and source_ids[key] for key in CAMERAS):
            raise ValueError("Camera source ID missing")
        self.source_ids = dict(source_ids)
        self.archives = None
        self.frames = 0
        self.closed = False
        self.binding = binding

    def bind(self, world, ego):
        if self.binding is not None:
            self.binding(world, ego)

    def _open(self):
        self.output.mkdir(parents=True, exist_ok=True)
        if any((self.output / (key + ".zip")).exists() for key in CAMERAS):
            raise ValueError("Original camera archive already exists")
        self.archives = {key: zipfile.ZipFile(self.output / (key + ".zip"), "w",
                         compression=zipfile.ZIP_STORED) for key in CAMERAS}

    def __call__(self, native_frame: int) -> dict:
        if self.closed or type(native_frame) is not int or native_frame < 0:
            raise ValueError("Camera recorder closed or frame invalid")
        images = self.frame_reader(native_frame)
        if not isinstance(images, dict) or set(images) != set(CAMERAS):
            raise ValueError("Four original camera images required")
        encoded = {}
        for key in CAMERAS:
            image = images[key]
            width, height = self.sizes[key]
            if (getattr(image, "frame", None) != native_frame or
                    getattr(image, "width", None) != width or
                    getattr(image, "height", None) != height):
                raise ValueError("Original camera frame or dimensions mismatch: " + key)
            raw = bytes(image.raw_data)
            if len(raw) != width * height * 4:
                raise ValueError("Original BGRA byte count mismatch: " + key)
            rgb = Image.frombytes("RGBA", (width, height), raw, "raw", "BGRA").convert("RGB")
            stream = io.BytesIO()
            rgb.save(stream, format="PNG")
            encoded[key] = stream.getvalue()
        if self.archives is None:
            self._open()
        name = f"{native_frame}.png"
        for key in CAMERAS:
            self.archives[key].writestr(name, encoded[key])
        self.frames += 1
        return {key: key + ".zip#" + name for key in CAMERAS}

    def finish(self, receipt: dict) -> dict:
        if self.closed or self.archives is None:
            raise ValueError("Camera recorder has no open capture")
        if receipt.get("case_id") != self.case_id or receipt.get("source_kind") != "original_capture":
            raise ValueError("Original capture receipt identity mismatch")
        first = receipt.get("native_first_frame")
        last = receipt.get("native_last_frame")
        if type(first) is not int or last != first + self.frames - 1 or self.frames != 900:
            raise ValueError("Original camera frame count incomplete")
        for archive in self.archives.values():
            archive.close()
        self.closed = True
        receipt_bytes = (self.output / "capture_receipt.json").read_bytes()
        if json.loads(receipt_bytes) != receipt:
            raise ValueError("Original capture receipt bytes differ")
        media = {"case_id": self.case_id,
                 "capture_receipt_sha256": hashlib.sha256(receipt_bytes).hexdigest(),
                 "source_ids": self.source_ids,
                 "cameras": {}}
        for key in CAMERAS:
            path = self.output / (key + ".zip")
            media["cameras"][key] = {"path": path.name,
                                     "sha256": hashlib.sha256(path.read_bytes()).hexdigest()}
        manifest = self.output / "camera_media.json"
        if manifest.exists() or manifest.is_symlink():
            raise ValueError("Original camera manifest already exists")
        manifest.write_text(json.dumps(media, indent=2, sort_keys=True) + "\n")
        return media

    def abort(self) -> None:
        """Close pending archives after a failed Native attempt."""
        if self.archives is not None and not self.closed:
            for archive in self.archives.values():
                archive.close()
        self.closed = True

"""Frame-joined independent warning-device observations for Native capture.

The caller supplies an instrument reader. Its returned JSON bytes are retained
unaltered; this adapter cannot establish acoustic range or pedestrian hearing.
"""
from __future__ import annotations

import hashlib
import json
from pathlib import Path


class DeviceReadback:
    def __init__(self, sample_reader, *, source_type: str, source_citation: str):
        if source_type not in {"instrument_telemetry", "acoustic_monitor", "external_device_log"}:
            raise ValueError("Independent device instrument source type required")
        if not source_citation:
            raise ValueError("Independent device source citation required")
        self.sample_reader = sample_reader
        self.source_type = source_type
        self.source_citation = source_citation
        self.samples = []
        self.sample_ids = set()
        self.last_frame = None

    def for_frame(self, ego, native_frame: int) -> dict:
        if type(native_frame) is not int or native_frame < 0:
            raise ValueError("Native device frame invalid")
        if self.last_frame is not None and native_frame != self.last_frame + 1:
            raise ValueError("Independent device sample frame gap")
        original = self.sample_reader(ego, native_frame)
        if not isinstance(original, bytes):
            raise ValueError("Independent device sample must be original JSON bytes")
        try:
            sample = json.loads(original)
        except (ValueError, UnicodeDecodeError) as exc:
            raise ValueError("Independent device sample JSON invalid") from exc
        if not isinstance(sample, dict) or sample.get("native_frame") != native_frame:
            raise ValueError("Independent device sample frame mismatch")
        sample_id = sample.get("sample_id")
        if not isinstance(sample_id, str) or not sample_id or sample_id in self.sample_ids:
            raise ValueError("Independent device sample identity missing or reused")
        if any(type(sample.get(key)) is not bool for key in ("siren_active", "warning_lamp_active")):
            raise ValueError("Independent device state missing")
        if any(key in sample for key in ("siren_commanded", "warning_lamp_commanded")):
            raise ValueError("Command fields cannot serve as independent readback")
        if sample.get("source_type") != self.source_type or sample.get("source_citation") != self.source_citation:
            raise ValueError("Independent device sample source mismatch")
        self.samples.append(original)
        self.sample_ids.add(sample_id)
        self.last_frame = native_frame
        return {"siren_active": sample["siren_active"],
                "warning_lamp_active": sample["warning_lamp_active"],
                "source_type": self.source_type,
                "source_citation": self.source_citation}

    def seal(self, output: Path, first_frame: int, last_frame: int) -> dict:
        if not self.samples or len(self.samples) != last_frame - first_frame + 1 or self.last_frame != last_frame:
            raise ValueError("Independent device sample count incomplete")
        path = Path(output) / "device_samples.jsonl"
        if path.exists() or path.is_symlink():
            raise ValueError("Original device samples already exist")
        data = b"".join(sample.rstrip(b"\r\n") + b"\n" for sample in self.samples)
        path.write_bytes(data)
        return {"path": path.name, "sha256": hashlib.sha256(data).hexdigest()}

"""Independent, source-bound audit of original emergency-device traces.

This reports observed relationships. It does not determine statutory compliance,
audibility at 500 feet, warning intent, or actual recipient hearing.
"""
from __future__ import annotations

import hashlib
import json
from pathlib import Path


EVENTS = {"emergency_call", "immediate_pursuit_actual", "immediate_pursuit_suspected", "none"}


def _load_source(folder: Path, relative: str, expected_sha: str) -> bytes:
    if Path(relative).is_absolute() or ".." in Path(relative).parts:
        raise ValueError("Source path escapes capture")
    data = (folder / relative).read_bytes()
    if hashlib.sha256(data).hexdigest() != expected_sha:
        raise ValueError("Original source hash mismatch: " + relative)
    return data


def audit(folder: Path, source_manifest: dict) -> dict:
    if source_manifest.get("source_kind") != "original_capture":
        raise ValueError("Only original capture sources are auditable")
    refs = source_manifest.get("sources", {})
    required = {"device_trace", "dispatch_context", "equipment_record"}
    if not required.issubset(refs) or set(refs) - (required | {"site_packet", "camera_trace", "actor_trace", "device_samples"}):
        raise ValueError("Required source inventory incomplete")
    documents = {}
    for key, ref in refs.items():
        documents[key] = _load_source(folder, ref["path"], ref["sha256"])
    context = json.loads(documents["dispatch_context"])
    equipment = json.loads(documents["equipment_record"])
    samples = [json.loads(line) for line in documents["device_trace"].decode().splitlines() if line]
    if context.get("event") not in EVENTS or context.get("source_status") != "documented":
        raise ValueError("Event source missing or undocumented")
    if equipment.get("authorization_source") is None or equipment.get("device_installation_source") is None:
        raise ValueError("Authorization or device inventory missing")
    if len(samples) != 900 or [x.get("frame") for x in samples] != list(range(900)):
        raise ValueError("Original 45-second 20-Hz frame sequence incomplete")
    if "camera_trace" in documents:
        camera_samples = [json.loads(line) for line in documents["camera_trace"].decode().splitlines() if line]
        if len(camera_samples) != 900 or [x.get("frame") for x in camera_samples] != list(range(900)):
            raise ValueError("Original camera frame sequence incomplete")
        for device, camera in zip(samples, camera_samples):
            if camera.get("native_frame") != device.get("native_frame") or set(camera.get("sources", {})) != {"overview", "approach", "reference_corner", "driver_reference"}:
                raise ValueError("Original camera/source synchronization mismatch")
    if "actor_trace" in documents:
        actor_samples = [json.loads(line) for line in documents["actor_trace"].splitlines()]
        if len(actor_samples) != 900:
            raise ValueError("Original actor frame sequence incomplete")
        for device, actor in zip(samples, actor_samples):
            if (actor.get("frame") != device.get("frame") or
                    actor.get("native_frame") != device.get("native_frame")):
                raise ValueError("Original actor/source synchronization mismatch")
    if "device_samples" in documents:
        original_samples = [json.loads(line) for line in documents["device_samples"].splitlines()]
        if len(original_samples) != 900:
            raise ValueError("Independent device sample count incomplete")
        for device, original in zip(samples, original_samples):
            if (original.get("native_frame") != device.get("native_frame") or
                    original.get("siren_active") != device.get("siren_active") or
                    original.get("warning_lamp_active") != device.get("warning_lamp_active") or
                    original.get("source_type") != device.get("device_source_type") or
                    original.get("source_citation") != device.get("device_source_citation")):
                raise ValueError("Independent device sample and trace mismatch")
    for sample in samples:
        if not isinstance(sample.get("siren_active"), bool) or not isinstance(sample.get("warning_lamp_active"), bool):
            raise ValueError("Original device state missing")
        if abs(float(sample.get("elapsed_s", -1)) - sample["frame"] / 20) > 0.001:
            raise ValueError("Device trace timing mismatch")
    siren_frames = [x["frame"] for x in samples if x["siren_active"]]
    lamp_frames = [x["frame"] for x in samples if x["warning_lamp_active"]]
    event_start, event_end = context.get("event_interval_frames", [None, None])
    event_overlaps_siren = bool(siren_frames) and event_start is not None and all(event_start <= i <= event_end for i in siren_frames)
    return {
        "observed_siren_frames": len(siren_frames),
        "observed_warning_lamp_frames": len(lamp_frames),
        "event": context["event"],
        "all_siren_frames_within_documented_event": event_overlaps_siren,
        "lamp_without_siren_observed": bool(lamp_frames) and not siren_frames,
        "audibility_500ft_documentation_status": equipment.get("audibility_500ft_status", "unknown"),
        "recipient_hearing": "unknown",
        "warning_purpose": "requires_independent_review",
        "physical_status": "original_source_audit_only",
    }
